files.game.js:
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 800 },
      debug: false
    }
  },
  scene: { preload, create, update }
};

let player, platforms, coins, cursors, score = 0, scoreText;

const game = new Phaser.Game(config);

function preload() {
  // Create simple colored rectangles as sprites
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Player sprite (blue square)
  graphics.fillStyle(0x0000ff, 1);
  graphics.fillRect(0, 0, 32, 32);
  graphics.generateTexture('player', 32, 32);
  graphics.clear();

  // Platform sprite (brown rectangle)
  graphics.fillStyle(0x8B4513, 1);
  graphics.fillRect(0, 0, 200, 20);
  graphics.generateTexture('platform', 200, 20);
  graphics.clear();

  // Coin sprite (yellow circle)
  graphics.fillStyle(0xFFD700, 1);
  graphics.fillCircle(16, 16, 16);
  graphics.generateTexture('coin', 32, 32);
}

function create() {
  // Create platforms
  platforms = this.physics.add.staticGroup();
  platforms.create(400, 568, 'platform').setScale(4, 1).refreshBody();
  platforms.create(600, 400, 'platform');
  platforms.create(50, 250, 'platform');
  platforms.create(750, 220, 'platform');

  // Create player
  player = this.physics.add.sprite(100, 450, 'player');
  player.setBounce(0.2);
  player.setCollideWorldBounds(true);

  // Create coins
  coins = this.physics.add.group({
    key: 'coin',
    repeat: 11,
    setXY: { x: 12, y: 0, stepX: 70 }
  });

  coins.children.iterate(child => {
    child.setBounceY(Phaser.Math.FloatBetween(0.4, 0.8));
  });

  // Add collisions
  this.physics.add.collider(player, platforms);
  this.physics.add.collider(coins, platforms);
  this.physics.add.overlap(player, coins, collectCoin, null, this);

  // Input
  cursors = this.input.keyboard.createCursorKeys();

  // Score text
  scoreText = this.add.text(16, 16, 'Score: 0', { 
    fontSize: '32px', 
    fill: '#000' 
  });
}

function update() {
  if (cursors.left.isDown) {
    player.setVelocityX(-160);
  } else if (cursors.right.isDown) {
    player.setVelocityX(160);
  } else {
    player.setVelocityX(0);
  }

  if (cursors.up.isDown && player.body.touching.down) {
    player.setVelocityY(-500);
  }
}

function collectCoin(player, coin) {
  coin.disableBody(true, true);
  score += 10;
  scoreText.setText('Score: ' + score);

  if (coins.countActive(true) === 0) {
    scoreText.setText('You Win! Score: ' + score);
  }
}
